{
  "steps": [
    {
      "title": "შეავსე ბიურეტი",
      "text": "ონკანი დახურულია? ძაბრით ჩაასხი ტიტრანტი ნულოვან ნიშნულზე ოდნავ მაღლა.",
      "focus": ["p4", "p1", "p2"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "შეამოწმე, რომ დახურულია", "tone": "brand"},
        {"part": "p1", "label": "ტიტრანტი ჩაასხი აქ", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ტიტრანტი", "დამცავი სათვალე", "შესაბამისი დამცავი ხელთათმანები"],
      "warn": "ფოტოდან ონკანის დახურულობა და ნულოვანი ნიშნული საიმედოდ არ დასტურდება; ადგილზე გადაამოწმე. გამოიყენე ტიტრანტის უსაფრთხოების ინსტრუქციით გათვალისწინებული დაცვა."
    },
    {
      "title": "მოხსენი ძაბრი",
      "text": "ძაბრი ტიტრაციამდე აუცილებლად მოხსენი. მისგან ჩამოსული წვეთები მოცულობას გააფუჭებს.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "მოსახსნელი ძაბრი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "ძაბრი ფრთხილად ამოიღე, რომ ბიურეტი არ გადაადგილდეს და ტიტრანტი არ დაიღვაროს."
    },
    {
      "title": "წაიკითხე საწყისი მოცულობა",
      "text": "თვალი სითხის დონეზე დაიჭირე და წაიკითხე მენისკის ქვედა კიდე. ჩაიწერე ჟურნალში.",
      "focus": ["p2"],
      "avoid": ["p4"],
      "markers": [
        {"part": "p2", "label": "მენისკი წაიკითხე თვალის დონეზე", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ჟურნალი", "კალამი"],
      "warn": "ფოტოზე სკალა და მენისკის ზუსტი მდებარეობა საკმარისად მკაფიო არ არის; მოცულობა უშუალოდ ბიურეტზე წაიკითხე."
    },
    {
      "title": "დაამატე ინდიკატორი",
      "text": "კოლბაში ჩააწვეთე 2–3 წვეთი ფენოლფთალეინი და დადე თეთრ ფილაზე ონკანის ქვეშ.",
      "focus": ["p6", "p5", "p7"],
      "avoid": [],
      "markers": [
        {"part": "p6", "label": "ინდიკატორის საწვეთური", "tone": "brand"},
        {"part": "p5", "label": "ჩააწვეთე კოლბაში", "tone": "brand"},
        {"part": "p7", "label": "კოლბის დასადგმელი ფილა", "tone": "neutral"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "ბოთლის შიგთავსი ფოტოდან ვერ დასტურდება; p6 ინდიკატორად მოცემული აღწერის მიხედვითაა მიჩნეული. გამოყენებამდე გადაამოწმე ეტიკეტი. 2–3 წვეთი მოცემული ინსტრუქციის დოზაა და არა ფოტოდან დადგენილი."
    },
    {
      "title": "ტიტრაცია",
      "text": "ონკანი ნელა გახსენი და კოლბა წრიულად ატრიალე. გაჩერდი, როცა ღია ვარდისფერი 30 წამს შენარჩუნდება.",
      "focus": ["p4", "p5"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "ნელა გახსენი; ბოლოს დახურე", "tone": "brand"},
        {"part": "p5", "label": "წრიულად არხიე და აკვირდი ფერს", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p5", "type": "rotate", "dir": "cw"}
      ],
      "tools": ["ტაიმერი"],
      "warn": "ონკანის გახსნის მიმართულება ფოტოდან ვერ განისაზღვრება; ძალა არ დაატანო. კოლბის წრიული მოძრაობა შეიძლება ორივე მიმართულებით. ღია ვარდისფერი და 30 წამი მოცემული მეთოდის კრიტერიუმებია; საბოლოო წერტილთან ტიტრანტი წვეთობრივად დაამატე."
    }
  ],
  "unknown_parts": []
}
